#pragma once
// Palette entries for the vehicle nodes (family version 2: the six original rows hold a vehicle by its physics handle, the fourteen
// appended ones by its entity). NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendVehicleNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphVehicleNodeTable.cs pin for pin
// (docs/plans/wave9/VISUAL_SCRIPTING_CSHARP_SYNC.md section 2.2). A vehicle is its integer handle (0 = none), the way an
// entity is. Create Car builds the default car (four wheels, front steered, rear driven) and the entity that follows it.

inline void appendVehicleNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_VehicleCreateCar", "Vehicle Create Car", "Vehicle", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("yaw", "float", false), pin("massKg", "float", false, "1500"),
        pin("then", "exec", true), pin("vehicle", "int", true), pin("entity", "int", true)}});
    t.push_back({"AN_VehicleSetInput", "Vehicle Set Input", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("throttle", "float", false), pin("steer", "float", false),
        pin("brake", "float", false), pin("handbrake", "float", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleGetState", "Vehicle Get State", "Vehicle", {
        pin("vehicle", "int", false), pin("found", "bool", true), pin("speedCmS", "float", true),
        pin("x", "float", true), pin("y", "float", true), pin("z", "float", true), pin("yaw", "float", true)}});
    t.push_back({"AN_VehicleSetPose", "Vehicle Set Pose", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("yaw", "float", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleDestroy", "Vehicle Destroy", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleWheelContact", "Vehicle Wheel Contact", "Vehicle", {
        pin("vehicle", "int", false), pin("index", "int", false), pin("contact", "bool", true)}});

    // ---- version 2 (wave 10): by entity; mirrors GraphVehicleNodeTable.cs pin for pin ----
    t.push_back({"AN_VehicleSpawn", "Vehicle Spawn", "Vehicle", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false), pin("yaw", "float", false),
        pin("then", "exec", true), pin("vehicle", "int", true), pin("entity", "int", true), pin("success", "bool", true)},
        {attr("asset", "Vehicle asset (.ocvehicle path or preset: car, van, truck, bus, sports, tank)")}});
    t.push_back({"AN_VehicleDrive", "Vehicle Drive", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("throttle", "float", false), pin("steer", "float", false),
        pin("brake", "float", false), pin("handbrake", "float", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleShift", "Vehicle Shift", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("delta", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleSetGear", "Vehicle Set Gear", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("gear", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleGearMode", "Vehicle Gear Mode", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("manual", "bool", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleEnter", "Vehicle Enter", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("driver", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleExit", "Vehicle Exit", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("driver", "int", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleFlip", "Vehicle Flip", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("liftCm", "float", false, "50"), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleTune", "Vehicle Tune", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("value", "float", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("key", "Key (power, brake, grip, suspension, steer, drag, downforce, abs, tcs, manual, collisionperiod)")}});
    t.push_back({"AN_VehicleRepair", "Vehicle Repair", "Vehicle", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("amount", "float", false, "1"), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleTelemetry", "Vehicle Telemetry", "Vehicle", {
        pin("entity", "int", false), pin("found", "bool", true), pin("speedCmS", "float", true), pin("rpm", "float", true), pin("gear", "int", true),
        pin("throttle", "float", true), pin("steer", "float", true), pin("brake", "float", true), pin("wheelsOnGround", "int", true),
        pin("health", "float", true), pin("abs", "bool", true), pin("tcs", "bool", true)}});
    t.push_back({"AN_VehicleWheelState", "Vehicle Wheel State", "Vehicle", {
        pin("entity", "int", false), pin("index", "int", false), pin("found", "bool", true), pin("contact", "bool", true), pin("slipLong", "float", true),
        pin("slipLatDeg", "float", true), pin("loadN", "float", true), pin("compressionCm", "float", true), pin("angVelRadS", "float", true),
        pin("surfaceFriction", "float", true), pin("skidding", "bool", true)}});
    t.push_back({"AN_VehicleDriver", "Vehicle Driver", "Vehicle", {
        pin("entity", "int", false), pin("driver", "int", true)}});
    t.push_back({"AN_VehicleFromEntity", "Vehicle From Entity", "Vehicle", {
        pin("entity", "int", false), pin("vehicle", "int", true), pin("found", "bool", true)}});
}
